<template><div v-if="event" class="demo-widget alert-widget" :style="widgetStyle(widget.settings)"><span class="widget-kicker">{{ runtimeMode === 'browser-source' ? 'STREAM ALERT' : 'SIMULATED ALERT' }}</span><b>{{ headline }}</b><p>{{ detail }}</p></div></template>
<script setup>import { computed, watch } from 'vue'; import { widgetStyle,useWidgetEvents } from '../../widgetHelpers.js'; const props=defineProps({widget:{type:Object,required:true},runtimeMode:{type:String,default:'editor-preview'},runtimeConfig:{type:Object,default:null}}); const event=useWidgetEvents(props.widget,props.runtimeMode==='browser-source'?null:{topic:'stream.follow',actor:{displayName:'NovaRespawn'},payload:{}}); const kind=computed(()=>({ 'stream.follow':'follow','stream.subscription':'subscription','stream.cheer':'cheer','stream.raid':'raid','reward.redeemed':'redemption' }[event.value?.topic]));const config=computed(()=>props.runtimeConfig?.alerts?.[kind.value]||null);const headline=computed(()=>({follow:'New follower!',subscription:'New subscriber!',cheer:'Cheer received!',raid:'Raid incoming!',redemption:'Reward redeemed!'}[kind.value]||'Stream alert'));const detail=computed(()=>{const user=event.value?.actor?.displayName||'A community member',payload=event.value?.payload||{},template=config.value?.template||props.widget.settings.messageTemplate||'{user} triggered {event}';return template.replaceAll('{user}',user).replaceAll('{event}',kind.value||'event').replaceAll('{viewers}',String(payload.viewers||0)).replaceAll('{bits}',String(payload.bits||0)).replaceAll('{reward}',String(payload.rewardTitle||payload.reward||'a reward'))});watch(event,()=>{if(props.runtimeMode!=='browser-source'||!config.value?.soundUrl)return;const audio=new Audio(config.value.soundUrl);audio.volume=Number(config.value.volume??1);void audio.play().catch(()=>{})})</script>
